import Vue from 'vue'
import VueRouter from 'vue-router'
import Home from '../views/Home.vue'
import Login from '../views/Login.vue'
import Register from '../views/Register.vue'
import Admin from '../views/Admin.vue'
import ArticleDetail from '../views/ArticleDetail.vue'
import ArticleList from '../views/admin/ArticleList.vue'
import ArticleEdit from '../views/admin/ArticleEdit.vue'
import CategoryList from '../views/admin/CategoryList.vue'
import TagList from '../views/admin/TagList.vue'
import CommentList from '../views/admin/CommentList.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    name: 'Home',
    component: Home
  },
  {
    path: '/article/:id',
    name: 'ArticleDetail',
    component: ArticleDetail
  },
  {
    path: '/login',
    name: 'Login',
    component: Login
  },
  {
    path: '/register',
    name: 'Register',
    component: Register
  },
  {
    path: '/admin',
    component: Admin,
    children: [
      {
        path: '',
        redirect: 'articles'
      },
      {
        path: 'articles',
        name: 'AdminArticles',
        component: ArticleList,
        meta: { requiresAuth: true }
      },
      {
        path: 'article/new',
        name: 'AdminArticleNew',
        component: ArticleEdit,
        meta: { requiresAuth: true }
      },
      {
        path: 'article/edit/:id',
        name: 'AdminArticleEdit',
        component: ArticleEdit,
        meta: { requiresAuth: true }
      },
      {
        path: 'categories',
        name: 'AdminCategories',
        component: CategoryList,
        meta: { requiresAuth: true }
      },
      {
        path: 'tags',
        name: 'AdminTags',
        component: TagList,
        meta: { requiresAuth: true }
      },
      {
        path: 'comments',
        name: 'AdminComments',
        component: CommentList,
        meta: { requiresAuth: true }
      }
    ],
    meta: { requiresAuth: true }
  }
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

// Auth guard
router.beforeEach((to, from, next) => {
  if (to.matched.some(record => record.meta.requiresAuth)) {
    const token = localStorage.getItem('token')
    if (!token) {
      next({ name: 'Login' })
    } else {
      next()
    }
  } else {
    next()
  }
})

export default router
